import 'package:flutter/material.dart';import 'package:pdf/widgets.dart' as pw;import 'package:printing/printing.dart';
class Voce{final String nome;final double min,max,medio;const Voce(this.nome,this.min,this.max):medio=(min+max)/2;}
const LISTINO=[Voce("Bagno completo rifacimento",4000,8000),Voce("Punto acqua calda/fredda",120,200),Voce("Sanitario + rubinetteria",250,450),Voce("Doccia / Vasca posa",350,650),Voce("Caldaia installazione",1200,2000),Voce("Sifone / disostruzione",80,150),];
class Riga{Voce voce;int qty;double prezzo;Riga(this.voce,this.qty,this.prezzo);double get tot=>qty*prezzo;}
void main()=>runApp(const MaterialApp(home:Home(),debugShowCheckedModeBanner:false));
class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_H();}
class _H extends State<Home>{final cliente=TextEditingController();final List<Riga> righe=[];double get totale=>righe.fold(0,(s,r)=>s+r.tot);
Future<void> genPDF() async{final doc=pw.Document();doc.addPage(pw.Page(build:(c)=>pw.Column(children:[pw.Text("Bart - Idraulico Pro",style:pw.TextStyle(fontSize:20,fontWeight:pw.FontWeight.bold)),pw.Text("Cliente: ${cliente.text}"),pw.SizedBox(height:20),...righe.map((r)=>pw.Row(mainAxisAlignment:pw.MainAxisAlignment.spaceBetween,children:[pw.Text("${r.qty}x ${r.voce.nome}"),pw.Text("${r.tot.toStringAsFixed(2)}€")])),pw.Divider(),pw.Text("TOTALE: ${totale.toStringAsFixed(2)}€")])));await Printing.layoutPdf(onLayout:(f)=>doc.save());}
@override Widget build(BuildContext c){return Scaffold(appBar:AppBar(title:const Text("Bart - Idraulico Pro"),backgroundColor:Colors.blue),body:Column(children:[Padding(padding:const EdgeInsets.all(8),child:TextField(controller:cliente,decoration:const InputDecoration(labelText:"Cliente",border:OutlineInputBorder()))),Expanded(child:ListView.builder(itemCount:LISTINO.length,itemBuilder:(a,i){final v=LISTINO[i];return ListTile(title:Text(v.nome),subtitle:Text("${v.min.toInt()}-${v.max.toInt()}€"),trailing:const Icon(Icons.add),onTap:()=>setState(()=>righe.add(Riga(v,1,v.medio))));})),const Divider(),Expanded(child:ListView.builder(itemCount:righe.length,itemBuilder:(a,i){final r=righe[i];return ListTile(title:Text("${r.qty}x ${r.voce.nome}"),trailing:Text("${r.tot.toStringAsFixed(0)}€"));})),SizedBox(width:double.infinity,child:Padding(padding:const EdgeInsets.all(8),child:ElevatedButton.icon(onPressed:righe.isEmpty?null:genPDF,icon:const Icon(Icons.picture_as_pdf),label:const Text("GENERA PDF")))))]));}}
